    .systems-modal-menu::-webkit-scrollbar {
        display: none; /* Oculta a barra de rolagem no Chrome, Safari e Opera */
    }

    .menu-item {
        flex: 0 0 auto; /* Impede que os itens encolham */
        padding: 10px 15px;
    }

    .separator {
        display: none; /* Oculta o separador vertical */
    }

    .systems-modal-content {
        width: 100%;
        height: calc(100% - 80px); /* Ajusta a altura para preencher o espaço restante */
    }

    .close-button {
        position: absolute;
        top: 10px;
        right: 15px;
        background: none;
        border: none;
        font-size: 24px;
        color: #888;
        cursor: pointer;
        z-index: 1000;
        transition: color 0.3s ease;
    }

