sp_header_footer.script:
(function() {
    /* populate the 'data' object */
    /* e.g., data.table = $sp.getValue('table'); */

    var instanceName = gs.getProperty('instance_name');
    data.instanceName = instanceName;

    // Adiciona informações do usuário
    data.user_info = getUserInfo();

    // Widget de busca
    data.typeAheadSearch = $sp.getWidget('typeahead_global_sefaz', options.typeahead_search);

    /**
     * Obtém informações do usuário logado
     * @returns {Object} Informações do usuário ou objeto vazio se não estiver logado
     */
    function getUserInfo() {
        var userGR = gs.getUser();

        if (!userGR || !userGR.getID() || userGR.getName() == 'guest') {
            return {
                logged_in: false
            };
        }

        // Usuário está logado, retorna as informações
        var firstName = userGR.getFirstName() || '';
        var lastName = userGR.getLastName() || '';

        return {
            logged_in: true,
            user_id: userGR.getID(),
            name: userGR.getDisplayName() || (firstName + ' ' + lastName),
            first_name: firstName,
            last_name: lastName,
            email: userGR.getEmail() || ''
        };
    }

    // Endpoint para logout
    if (input && input.action === 'logout') {
        gs.invalidateSession();
        return {
            success: true,
            message: 'Logout realizado com sucesso'
        };
    }

/* FUNCIONALIDADE DE CACHE */

	   var ACCESS_THROTTLE_SECONDS = 30; // Ex: 30 segundos

    data.isLoggedIn = gs.isLoggedIn();

    // --- FUNÇÕES AUXILIARES ---
    var TABLE_NAME = 'x_sded9_portal_t_0_acessos_do_portal';

    // --- 1. LÓGICA DE REGISTRO (Executada APENAS se houver input) ---
    if (input && input.action === 'log_access') {
        var currentIdentifier = null;
        var queryField = null;

        if (input.isLoggedIn) {
            currentIdentifier = gs.getUserID();
            queryField = 'u_usuario';
        } else if (input.anonId) {
            currentIdentifier = input.anonId;
            queryField = 'u_anonimo_id';
        }

        if (currentIdentifier) {
            var pageId = input.contextPageId || 'page_id_desconhecido';
            var now = new GlideDateTime();

            // --- LÓGICA DE VERIFICAÇÃO DE DUPLICAÇÃO ---
            var grCheck = new GlideRecord(TABLE_NAME);
            grCheck.addQuery(queryField, currentIdentifier); // Busca pelo identificador
            grCheck.addQuery('u_pagina_url', pageId); // E pela URL
            grCheck.orderByDesc('u_hora_do_acesso'); // Pega o mais recente
            grCheck.setLimit(1);
            grCheck.query();

            if (grCheck.next()) {
                // 1. Pega o último acesso como um objeto GlideDateTime
                var lastAccessDT = new GlideDateTime(grCheck.getValue('u_hora_do_acesso'));

                // 2. Cria uma cópia do tempo atual para fazer a subtração
                var nowCopy = new GlideDateTime(now);

                // 3. Usa o método subtract() na cópia do tempo atual, subtraindo o último acesso
                var duration = nowCopy.subtract(lastAccessDT);

                // 4. Obtém o resultado em segundos (corrigido para o método GlideDuration)
                var diffSeconds = duration.getNumericValue() / 1000; // Retorna milissegundos, divide por 1000 para segundos

                // Se o último acesso foi DENTRO do intervalo de 30 segundos, não registra
                if (diffSeconds < ACCESS_THROTTLE_SECONDS) {
                    data.success = false; // Sinaliza que não houve registro (por throttle)
                    return; // Sai da função sem inserir o registro
                }
            }
            // --- FIM DA LÓGICA DE VERIFICAÇÃO ---

					var session = gs.getSession();
					var addr = session.getClientIP();
					gs.info(addr);

            // Se passou na verificação (ou não havia registro anterior), insere o novo
            var gr = new GlideRecord(TABLE_NAME);
            gr.initialize();
            gr.setValue(queryField, currentIdentifier);
            gr.setValue('u_hora_do_acesso', now); // Usa o tempo atual
            gr.setValue('u_pagina_url', pageId);
						gr.setValue('u_ip', addr);
            gr.insert();

            data.success = true; // Registro bem-sucedido
        } else {
            data.success = false;
        }
    }



})();
